import{H as e,M as t,j as n,o as r}from"./chunks/framework.3mupUg1I.js";var i=JSON.parse(`{"title":"Investigative Report: Amazon AI Training Facility Linked to Rare Book Shipments","description":"An investigation tracked a shipment of rare books to an Amazon AI training facility, exposing the secretive methods used to acquire data for large language models.","frontmatter":{"layout":"article","title":"Investigative Report: Amazon AI Training Facility Linked to Rare Book Shipments","description":"An investigation tracked a shipment of rare books to an Amazon AI training facility, exposing the secretive methods used to acquire data for large language models.","photo":"https://picsum.photos/id/795/800/450","original_url":"https://simonwillison.net/2026/Aug/17/we-tracked-a-shipment-of-rare-books-it-ended-at-an-amazon-ai-tra/","source_name":"Simon Willison's Weblog","source_author":"Simon Willison","tags":["ai","research","ai-ethics","llm"],"significance":4,"head":[["link",{"rel":"canonical","href":"https://digestweb.dev/articles/2026-08-17/amazon-ai-training-rare-books-investigation"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Investigative Report: Amazon AI Training Facility Linked to Rare Book Shipments"}],["meta",{"property":"og:description","content":"An investigation tracked a shipment of rare books to an Amazon AI training facility, exposing the secretive methods used to acquire data for large language models."}],["meta",{"property":"og:url","content":"https://digestweb.dev/articles/2026-08-17/amazon-ai-training-rare-books-investigation"}],["meta",{"property":"og:site_name","content":"digestweb.dev"}],["meta",{"property":"og:image","content":"https://picsum.photos/id/795/800/450"}],["meta",{"property":"article:published_time","content":"2026-08-17T00:00:00.000Z"}],["meta",{"property":"article:author","content":"Simon Willison"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Investigative Report: Amazon AI Training Facility Linked to Rare Book Shipments"}],["meta",{"name":"twitter:description","content":"An investigation tracked a shipment of rare books to an Amazon AI training facility, exposing the secretive methods used to acquire data for large language models."}],["meta",{"name":"twitter:image","content":"https://picsum.photos/id/795/800/450"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"NewsArticle\\",\\"headline\\":\\"Investigative Report: Amazon AI Training Facility Linked to Rare Book Shipments\\",\\"description\\":\\"An investigation tracked a shipment of rare books to an Amazon AI training facility, exposing the secretive methods used to acquire data for large language models.\\",\\"url\\":\\"https://digestweb.dev/articles/2026-08-17/amazon-ai-training-rare-books-investigation\\",\\"datePublished\\":\\"2026-08-17T00:00:00.000Z\\",\\"image\\":\\"https://picsum.photos/id/795/800/450\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Simon Willison\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"digestweb.dev\\",\\"url\\":\\"https://digestweb.dev\\"}}"]]},"headers":[],"relativePath":"articles/2026-08-17/amazon-ai-training-rare-books-investigation.md","filePath":"articles/2026-08-17/amazon-ai-training-rare-books-investigation.md"}`),a={name:`articles/2026-08-17/amazon-ai-training-rare-books-investigation.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h2 id="summary-key-takeaways" tabindex="-1">Summary &amp; Key Takeaways <a class="header-anchor" href="#summary-key-takeaways" aria-label="Permalink to “Summary &amp; Key Takeaways”">​</a></h2><ul><li>An investigative report tracked a shipment of rare books to an Amazon AI training facility in Las Vegas.</li><li>The books were ordered by apparently price-insensitive, anonymous customers, suspected to be AI companies.</li><li>An AirTag placed in one of the books confirmed its destination at an Amazon facility (VGT3/LAS8).</li><li>Online forum discussions among Amazon workers corroborate that VGT3 destructively scans large volumes of books.</li><li>This investigation sheds light on the opaque practices of AI companies acquiring training data.</li><li>The findings raise significant ethical questions about data sourcing for large language models.</li></ul><h2 id="our-commentary" tabindex="-1">Our Commentary <a class="header-anchor" href="#our-commentary" aria-label="Permalink to “Our Commentary”">​</a></h2><p>Okay, this is a headline. We tracked a shipment of rare books with an AirTag, and it ended up at an Amazon AI training facility? That&#39;s some next-level investigative journalism. I&#39;ve heard the whispers about AI companies hoovering up books, but seeing it confirmed like this is unsettling. It makes you wonder what other data is being acquired through these opaque channels. There&#39;s something deeply uncomfortable about the destructive scanning of books for AI. This isn&#39;t just about data; it&#39;s about the ethics of how we feed these models. We need more transparency, now.</p>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};